<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { detallePreTicket,eliminarPreTicket,listarPreTickets,validarPreTicket,type Options,type PreTicket } from '../services/atencionExterna'
const rows=ref<PreTicket[]>([]),options=ref<Options>({conceptos:[],distritos:[],parentescos:[]}),total=ref(0),lastPage=ref(1),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),detail=ref<PreTicket|null>(null),modal=ref(false)
const filters=reactive({criterio:'',distrito_id:'',desde:'',hasta:'',page:1}),form=reactive({apellido_paterno:'',apellido_materno:'',nombre:'',dni:'',celular:'',telefono_fijo:'',email:'',parentesco:'',distrito_id:'',suministro:'',descripcion:'',tipo_atencion_id:''})
const concept=computed(()=>options.value.conceptos.find(x=>String(x.id)===String(form.tipo_atencion_id)))
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await listarPreTickets(filters);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page;options.value=r.options}catch(e){error.value=message(e)}finally{loading.value=false}}
async function show(item:PreTicket){try{detail.value=await detallePreTicket(item.id)}catch(e){error.value=message(e)}}async function open(item:PreTicket){try{detail.value=await detallePreTicket(item.id)}catch{detail.value=item}Object.assign(form,{apellido_paterno:detail.value.apellido_paterno,apellido_materno:detail.value.apellido_materno,nombre:detail.value.nombre,dni:detail.value.dni,celular:detail.value.celular,telefono_fijo:detail.value.telefono_fijo||'',email:detail.value.email,parentesco:detail.value.parentesco,distrito_id:detail.value.distrito_id,suministro:detail.value.suministro||'',descripcion:detail.value.descripcion,tipo_atencion_id:''});modal.value=true}
async function submit(){if(!detail.value||!/^\d{8}$/.test(form.dni)||!/^\d{9}$/.test(form.celular)||!form.email.includes('@')||form.descripcion.trim().length<20||!form.tipo_atencion_id){error.value='Revise DNI, celular, correo, descripción y tipo de atención.';return}if(concept.value?.requiere_conexion&&(!form.suministro||form.suministro.length<8)){error.value='El tipo de atención seleccionado requiere un suministro válido.';return}saving.value=true;error.value='';try{const r=await validarPreTicket(detail.value.id,form);modal.value=false;detail.value=null;success.value=`Pre-ticket validado. Se generó el ticket #${r.ticket_id}.`;await load(1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function remove(item:PreTicket){if(!confirm(`¿Descartar el pre-ticket #${item.id}?`))return;try{await eliminarPreTicket(item.id);success.value='Pre-ticket descartado correctamente.';detail.value=null;await load()}catch(e){error.value=message(e)}}function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Comercialización / Atención Externa</nav><header class="hero"><div class="mark">AE</div><div><small>EVAN · COMERCIALIZACIÓN</small><h1>Atención externa</h1><p>Validación de solicitudes ciudadanas recibidas mediante el portal público.</p></div><strong>{{total}} pendientes</strong></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="filters"><label>Buscar<input v-model.trim="filters.criterio" placeholder="Código, DNI, nombre o suministro" @keyup.enter="load(1)"></label><label>Distrito<select v-model="filters.distrito_id"><option value="">Todos</option><option v-for="x in options.distritos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Desde<input v-model="filters.desde" type="date"></label><label>Hasta<input v-model="filters.hasta" type="date"></label><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando solicitudes externas…</div><div v-else-if="!rows.length" class="empty">No existen pre-tickets pendientes de validación.</div>
<section v-else class="cards"><article v-for="item in rows" :key="item.id"><header><div><small>PRE-TICKET</small><b>#{{String(item.id).padStart(6,'0')}}</b></div><time>{{item.fecha_registro}}</time></header><h2>{{item.nombre_completo||`${item.apellido_paterno} ${item.apellido_materno}, ${item.nombre}`}}</h2><strong>DNI {{item.dni}}</strong><p>{{item.descripcion}}</p><dl><div><dt>Distrito</dt><dd>{{item.distrito}}</dd></div><div><dt>Suministro</dt><dd>{{item.suministro||'No indicado'}}</dd></div><div><dt>Contacto</dt><dd>{{item.celular}}<small>{{item.email}}</small></dd></div></dl><footer><button @click="show(item)">Ver</button><button class="good" @click="open(item)">Validar</button><button class="danger" @click="remove(item)">Descartar</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="detail&&!modal" class="backdrop" @mousedown.self="detail=null"><section class="modal detail"><header><div><small>PRE-TICKET #{{detail.id}}</small><h2>{{detail.nombre_completo||detail.nombre}}</h2><p>DNI {{detail.dni}} · {{detail.fecha_registro}}</p></div><button @click="detail=null">×</button></header><div class="summary"><div><b>{{detail.distrito}}</b><span>Distrito</span></div><div><b>{{detail.suministro||'—'}}</b><span>Suministro</span></div><div><b>{{detail.parentesco}}</b><span>Relación</span></div></div><p class="description">{{detail.descripcion}}</p><h3>Contacto</h3><p>{{detail.celular}} · {{detail.telefono_fijo||'Sin teléfono fijo'}} · {{detail.email}}</p><h3>Documento adjunto</h3><p>{{detail.archivo||'No se adjuntó evidencia.'}}</p><footer><button class="clear" @click="detail=null">Cerrar</button><button class="danger-bg" @click="remove(detail)">Descartar</button><button @click="open(detail)">Validar solicitud</button></footer></section></div>
<div v-if="modal&&detail" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="submit"><header><div><small>VALIDACIÓN DEL PRE-TICKET #{{detail.id}}</small><h2>Generar ticket comercial</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Nombres *<input v-model.trim="form.nombre" minlength="2"></label><label>Apellido paterno *<input v-model.trim="form.apellido_paterno" minlength="2"></label><label>Apellido materno *<input v-model.trim="form.apellido_materno" minlength="2"></label><label>DNI *<input v-model.trim="form.dni" maxlength="8"></label><label>Celular *<input v-model.trim="form.celular" maxlength="9"></label><label>Teléfono fijo<input v-model.trim="form.telefono_fijo" maxlength="7"></label><label>Correo *<input v-model.trim="form.email" type="email"></label><label>Parentesco<select v-model="form.parentesco"><option v-for="x in options.parentescos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Distrito *<select v-model="form.distrito_id"><option v-for="x in options.distritos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Tipo de atención *<select v-model="form.tipo_atencion_id"><option value="">Seleccione</option><option v-for="x in options.conceptos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label v-if="concept?.requiere_conexion">Suministro *<input v-model.trim="form.suministro" inputmode="numeric"></label></div><label>Descripción *<textarea v-model.trim="form.descripcion" minlength="20" rows="5"></textarea></label><p class="notice">Al confirmar se creará o actualizará la persona y se generará un ticket en la bandeja principal de Atención al Cliente.</p><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Validando…':'Validar y generar ticket'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#21a06b;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.6rem;font-weight:700}.hero small,.modal small{color:var(--accent);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p,.modal header p{margin:0;color:#7d898f;font-size:.65rem}.hero strong{margin-left:auto;font-size:.58rem}.filters button,.pages button,.modal footer button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.56rem}.flash{padding:10px;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.63rem}.flash.error{color:#a13f43;background:#fff0f0}.filters{margin-top:13px;padding:12px;display:flex;align-items:end;gap:7px;border-radius:9px;background:#fff}.filters label{flex:1;font-size:.52rem}.filters label:first-child{flex:2}input,select,textarea{width:100%;padding:8px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.59rem}.cards{margin-top:13px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{display:flex;flex-direction:column;padding:14px;border-top:3px solid #d89936;border-radius:9px;background:#fff}.cards article>header{display:flex;justify-content:space-between}.cards header small,.cards header b{display:block}.cards header time{color:#7d898f;font-size:.49rem}.cards h2{font-size:.65rem}.cards article>strong{font-size:.52rem}.cards article>p{min-height:48px;color:#68767d;font-size:.55rem}.cards dl{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.cards dt{color:#8a969c;font-size:.46rem}.cards dd{margin:2px 0;font-size:.51rem;font-weight:700}.cards dd small{display:block}.cards footer{margin-top:auto;display:flex;justify-content:flex-end}.cards footer button{border:0;color:#65747b;background:none;font-size:.49rem}.cards footer .good{color:var(--accent)}.cards footer .danger{color:#a13f43}.empty{margin-top:13px;padding:45px;text-align:center;background:#fff;font-size:.63rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.55rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,820px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin-bottom:10px;font-size:.56rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.summary{margin:14px 0;display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.summary div{padding:11px;text-align:center;border-radius:7px;background:#eff9f4}.summary b,.summary span{display:block;font-size:.53rem}.description,.notice{padding:11px;border-left:3px solid var(--accent);background:#f6f8f9;font-size:.57rem}.notice{border-color:#d89936}.modal h3{font-size:.65rem}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.danger-bg{background:#a13f43!important}.detail{width:min(100%,850px)}@media(max-width:900px){.cards{grid-template-columns:1fr 1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}}@media(max-width:560px){.cards,.grid,.summary{grid-template-columns:1fr}}
</style>
